require dirname(__DIR__).'/app/bootstrap.php';admin_required();
$id=max(0,scalar_int($_GET['id']??0));$orderId=max(0,scalar_int($_GET['order_id']??$_POST['order_id']??0));$shipment=null;if($id>0){$stmt=db()->prepare('SELECT * FROM shipments WHERE id=?');$stmt->execute([$id]);$shipment=$stmt->fetch()?:null;if(!$shipment){http_response_code(404);exit('پرونده ارسال پیدا نشد.');}$orderId=(int)$shipment['order_id'];}$stmt=db()->prepare('SELECT * FROM orders WHERE id=?');$stmt->execute([$orderId]);$order=$stmt->fetch();if(!$order){http_response_code(404);exit('سفارش پیدا نشد.');}
if(is_post()){
    verify_csrf();
    try{$sendSms=isset($_POST['send_sms']);$saveResult=save_shipment($orderId,scalar_int($_POST['carrier_id']??0)?:null,scalar_string($_POST['tracking_code']??''),scalar_string($_POST['status']??'pending'),scalar_int($_POST['package_count']??1,1),scalar_int($_POST['weight_grams']??0),scalar_int($_POST['shipping_cost']??0),scalar_string($_POST['note']??''),scalar_string($_POST['event_text']??''),scalar_string($_POST['location']??''),$sendSms);$shipmentId=(int)$saveResult['shipment_id'];flash('success','پرونده ارسال و رویداد رهگیری ذخیره شد.');if($sendSms){if(is_array($saveResult['sms']??null))sms_admin_flash_immediate_result($saveResult['sms'],'پیامک وضعیت و رهگیری');elseif(empty($saveResult['changed']))flash('error','وضعیت، کد رهگیری یا شرکت حمل تغییری نکرد؛ پیامکی ارسال نشد.');}redirect(app_url('admin/shipment.php?id='.$shipmentId));}catch(Throwable $e){flash('error',$e->getMessage());redirect(app_url('admin/shipment.php'.($shipment?'?id='.$shipment['id']:'?order_id='.$orderId)));}
}
$shipment=shipment_for_order($orderId);$events=[];if($shipment){$e=db()->prepare('SELECT se.*,a.full_name admin_name FROM shipment_events se LEFT JOIN admins a ON a.id=se.admin_id WHERE se.shipment_id=? ORDER BY se.id DESC');$e->execute([(int)$shipment['id']]);$events=$e->fetchAll();}$carriers=db()->query('SELECT * FROM shipping_carriers WHERE is_active=1 ORDER BY sort_order,name')->fetchAll();$totalWeight=0;$w=db()->prepare('SELECT oi.quantity,COALESCE(pv.weight_grams,p.weight_grams) weight FROM order_items oi JOIN products p ON p.id=oi.product_id LEFT JOIN product_variants pv ON pv.id=oi.variant_id WHERE oi.order_id=?');$w->execute([$orderId]);foreach($w->fetchAll() as $row)$totalWeight+=(int)$row['quantity']*(int)$row['weight'];$adminPage='shipments';$adminTitle='ارسال سفارش '.$order['order_number'];require __DIR__.'/partials/header.php';
?>
<div class="admin-title"><div><h1>ارسال سفارش <?=e($order['order_number'])?></h1><p class="muted"><?=e($order['customer_name'].' · '.$order['phone'])?></p></div><div class="admin-actions"><a class="btn btn-secondary" href="<?=e(app_url('admin/shipments.php'))?>">بازگشت</a><?php if($shipment):?><a class="btn btn-secondary" target="_blank" href="<?=e(app_url('track-order.php?order='.rawurlencode($order['order_number'])))?>">صفحه رهگیری مشتری</a><?php endif?></div></div><div class="card"><strong>مقصد:</strong> <?=e($order['province'].'، '.$order['city'].'، '.$order['address'])?><br><strong>کدپستی:</strong> <?=e($order['postal_code'])?></div><form method="post" class="card"><?=csrf_field()?><input type="hidden" name="order_id" value="<?=$orderId?>"><div class="form-grid"><div class="field"><label>شرکت حمل</label><select name="carrier_id"><option value="0">تعیین نشده</option><?php foreach($carriers as $carrier):?><option value="<?=$carrier['id']?>" <?=($shipment['carrier_id']??0)==$carrier['id']?'selected':''?>><?=e($carrier['name'])?></option><?php endforeach?></select></div><div class="field"><label>کد رهگیری / بارنامه</label><input name="tracking_code" dir="ltr" maxlength="150" value="<?=e($shipment['tracking_code']??'')?>"></div><div class="field"><label>وضعیت</label><select name="status"><?php $currentShipmentStatus=(string)($shipment['status']??'pending');foreach(shipment_status_labels() as $key=>$label):if($key!==$currentShipmentStatus&&!shipment_transition_allowed($currentShipmentStatus,$key))continue;?><option value="<?=e($key)?>" <?=$currentShipmentStatus===$key?'selected':''?>><?=e($label)?></option><?php endforeach?></select></div><div class="field"><label>تعداد بسته</label><input type="number" name="package_count" min="1" max="100" value="<?=e($shipment['package_count']??1)?>"></div><div class="field"><label>وزن کل، گرم</label><input type="number" name="weight_grams" min="0" value="<?=e($shipment['weight_grams']??$totalWeight)?>"></div><div class="field"><label>هزینه واقعی حمل</label><input type="number" name="shipping_cost" min="0" value="<?=e($shipment['shipping_cost']??0)?>"></div><div class="field full"><label>متن رویداد رهگیری</label><input name="event_text" maxlength="500" placeholder="مثلاً بسته وارد مرکز مبادلات شد"></div><div class="field"><label>موقعیت رویداد</label><input name="location" maxlength="180" placeholder="تهران"></div><div class="field full"><label>یادداشت داخلی</label><textarea name="note" maxlength="3000"><?=e($shipment['note']??'')?></textarea></div><div class="field full"><label><input type="checkbox" name="send_sms" value="1" checked> ارسال پیامک وضعیت و کد رهگیری پس از تکمیل پرداخت (بدون انتظار برای Cron)</label></div></div><button class="btn btn-primary">ذخیره رویداد ارسال</button></form><?php if($events):?><div class="card"><h2>تاریخچه رهگیری</h2><div class="timeline"><?php foreach($events as $event):?><div class="timeline-item"><strong><?=e(shipment_status_labels()[$event['status']]??$event['status'])?></strong> — <?=e($event['event_text'])?><?php if($event['location']):?> · <?=e($event['location'])?><?php endif?><br><small><?=e(jalali_format($event['created_at']))?> · <?=e($event['admin_name']?:'سیستم')?></small></div><?php endforeach?></div></div><?php endif?>
